#!/usr/bin/env bash
set -euo pipefail

# Test: branch-guard sibling-repo exemption + plan-mode soften + /save PR dedupe
# Generated by /qa on 2026-04-18
# Covers:
#   .claude/hooks/branch-guard.sh
#   .claude/skills/save/SKILL.md (shared transaction delegation)
#   bin/agent.sh (clean-tree PR publication and reuse)
#   bin/handoff-save-egregore.sh (background-save ahead check and PR reuse)
#   .claude/skills/wrap/SKILL.md (session_duration_ms derivation)

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$SCRIPT_DIR/.claude/hooks/branch-guard.sh"
SAVE_MD="$SCRIPT_DIR/.claude/skills/save/SKILL.md"
AGENT_SH="$SCRIPT_DIR/bin/agent.sh"
BACKGROUND_SAVE_SH="$SCRIPT_DIR/bin/handoff-save-egregore.sh"
CLAUDE_MD="$SCRIPT_DIR/CLAUDE.md"

PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    → $2"; }

echo "Testing: branch-guard + /save dedupe + /wrap duration"
echo

# ─────────────────────────────────────────────────────────
# branch-guard.sh — runtime behavior on a real develop branch
# ─────────────────────────────────────────────────────────

echo "── branch-guard runtime ──"

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
cd "$TMP"
git init -q
git checkout -q -b develop
git -c user.email=t@t -c user.name=t commit --allow-empty -q -m init
export CLAUDE_PROJECT_DIR="$TMP"

# 1) EnterPlanMode on develop must now exit 0 (softened)
set +e
echo '{"tool_name":"EnterPlanMode","tool_input":{}}' | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "EnterPlanMode on develop → allowed (soften fix)"
else
  fail "EnterPlanMode on develop → blocked with exit $rc" "expected 0"
fi

# 2) Write to sibling dir outside PROJECT_DIR must exit 0 (sibling-repo fix)
SIBLING=$(mktemp -d)
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$SIBLING/file.md\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
rm -rf "$SIBLING"
if [ "$rc" -eq 0 ]; then
  pass "Write to sibling repo (outside PROJECT_DIR) on develop → allowed"
else
  fail "Write to sibling repo on develop → blocked with exit $rc" "expected 0 after sibling-repo exemption"
fi

# 3) Write to a project-internal path on develop must block (exit 2)
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/src/f.py\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 2 ]; then
  pass "Write to project-internal path on develop → blocked (exit 2)"
else
  fail "Write to project-internal path on develop → exit $rc" "expected 2"
fi

# 4) Block message mentions AskUserQuestion
set +e
MSG=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/src/f.py\"}}" | bash "$HOOK" 2>&1 >/dev/null)
set -e
if grep -q "AskUserQuestion" <<< "$MSG"; then
  pass "block message instructs Claude to use AskUserQuestion"
else
  fail "block message missing AskUserQuestion directive" "got: $MSG"
fi
if grep -q "create the branch automatically" <<< "$MSG" &&
   ! grep -q "Ask the user how to proceed" <<< "$MSG"; then
  pass "clear-topic path auto-branches without a routine Git prompt"
else
  fail "block message still interrupts for routine branch permission" "got: $MSG"
fi

# 5) Write to .claude/ on develop must still be allowed (pre-existing exemption intact)
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/.claude/foo.md\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass ".claude/ exemption on develop → still allowed"
else
  fail ".claude/ exemption broke" "exit $rc"
fi

# 6) The documented consent command must never be blocked by the guard itself
set +e
echo "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"echo 'develop' > .egregore-branch-consent\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "protected-branch consent command → allowed"
else
  fail "consent command blocked itself" "exit $rc"
fi

# 7) Memory-only shell preparation must not force a project branch
set +e
echo "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"mkdir -p memory/knowledge/harvests/test\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "memory-only shell preparation on develop → allowed"
else
  fail "memory-only shell preparation unexpectedly blocked" "exit $rc"
fi

# 8) On a non-protected branch the hook must short-circuit to allow everything
git checkout -q -b dev/test/topic
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/src/f.py\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "on non-protected branch → hook short-circuits (allow)"
else
  fail "non-protected branch unexpectedly blocked" "exit $rc"
fi

cd "$SCRIPT_DIR"

# ─────────────────────────────────────────────────────────
# /save — dedupe pattern present in both flows
# ─────────────────────────────────────────────────────────

echo
echo "── /save PR dedupe ──"

# Exercise the maintained transaction with a clean, committed task branch.
# Transport commands are local fakes; no repository or network mutation occurs.
sed -n '/^cmd_save() {$/,/^}$/p' "$AGENT_SH" > "$TMP/save-function.sh"
mkdir -p "$TMP/bin/lib"
: > "$TMP/bin/lib/noncode.sh"
cat > "$TMP/check-save.sh" <<'SAVETEST'
set -euo pipefail
fixture="$1"
existing_pr_url="$2"
SCRIPT_DIR="$fixture"
MEMORY_DIR="$fixture/no-memory"
resolve_base_branch() { echo integration; }
die() { echo "$*" >&2; exit 1; }
git() {
  [ "$1" = "-C" ] && shift 2
  printf 'git %s\n' "$*" >> "$fixture/transport.log"
  case "$*" in
    'branch --show-current') echo dev/test/committed ;;
    'status --porcelain') ;;
    'remote get-url origin') echo https://example.invalid/repo.git ;;
    'diff origin/integration...HEAD --name-only') echo src/change.js ;;
    'push -u origin dev/test/committed --quiet') ;;
    *) echo "unexpected git call: $*" >&2; return 1 ;;
  esac
}
gh() {
  printf 'gh %s\n' "$*" >> "$fixture/transport.log"
  case "$1 $2" in
    'pr list')
      jq -cn --arg url "$existing_pr_url" '
        if $url == "" then [] else [{url: $url, number: 41, isDraft: false}] end
      ' ;;
    'pr create') echo https://example.invalid/repo/pull/42 ;;
    *) echo "unexpected gh call: $*" >&2; return 1 ;;
  esac
}
. "$fixture/save-function.sh"
cmd_save --message 'fix(test): publish committed work' --pr-body 'fixture PR body'
SAVETEST

if bash "$TMP/check-save.sh" "$TMP" '' > "$TMP/save-output" &&
   grep -Fq 'git push -u origin dev/test/committed --quiet' "$TMP/transport.log" &&
   grep -Fq 'gh pr create --base integration --head dev/test/committed' "$TMP/transport.log" &&
   grep -Fq 'commit: false' "$TMP/save-output"; then
  pass "shared /save publishes a clean committed branch and creates its missing PR"
else
  fail "shared /save stopped on a clean branch with no PR"
fi
: > "$TMP/transport.log"
if bash "$TMP/check-save.sh" "$TMP" 'https://example.invalid/repo/pull/41' > "$TMP/save-output" &&
   grep -Fq 'gh pr list --head dev/test/committed --state open' "$TMP/transport.log" &&
   ! grep -Fq 'gh pr create' "$TMP/transport.log" &&
   grep -Fq 'pr: https://example.invalid/repo/pull/41' "$TMP/save-output"; then
  pass "shared /save reuses an existing PR for clean committed work"
else
  fail "shared /save did not reuse the existing PR"
fi

if grep -Fq 'git rev-list --count "$BASE_REF..HEAD"' "$BACKGROUND_SAVE_SH" &&
   grep -Fq '[ "$DIRTY" = "0" ] && [ "$AHEAD" = "0" ]' "$BACKGROUND_SAVE_SH" &&
   grep -Fq 'gh pr list --head "$CURRENT_BRANCH" --state open' "$BACKGROUND_SAVE_SH"; then
  pass "background save gates its clean-tree exit on ahead count and checks for an existing PR"
else
  fail "background save lost its committed-work or PR-reuse guard"
fi

# The skill delegates the Git transaction to bin/agent.sh save, which must
# look for an open PR on the branch before creating one.
if grep -Fq '`bin/agent.sh save` is the one runtime-neutral Git transaction' "$SAVE_MD" &&
   grep -Fq 'A clean tree can still need a push/PR when the branch is ahead.' "$SAVE_MD"; then
  pass "/save routes the transaction through bin/agent.sh save"
else
  fail "/save no longer routes through bin/agent.sh save"
fi
LIST_LINE=$(grep -nE 'gh pr list --head.*--state open' "$AGENT_SH" | head -1 | cut -d: -f1)
CREATE_LINE=$(grep -nE 'gh pr create ' "$AGENT_SH" | head -1 | cut -d: -f1)
if [ -n "$LIST_LINE" ] && [ -n "$CREATE_LINE" ] && [ "$LIST_LINE" -lt "$CREATE_LINE" ]; then
  pass "bin/agent.sh save checks for an open PR before creating one"
else
  fail "bin/agent.sh save could create a duplicate PR" "list=$LIST_LINE create=$CREATE_LINE"
fi

# No orphan `gh pr create` in operational code blocks without a dedupe check.
# Only count lines that look like actual shell commands (indented inside a code
# block — `    gh pr create` or `     gh pr create`), not prose mentions of
# the command name. Every such command must be preceded within 40 lines by a
# `gh pr list`.
awk '
  /gh pr list/ { last_list = NR }
  /^    *gh pr create/ {
    if (last_list == 0 || NR - last_list > 40) {
      print NR ":" $0
    }
  }
' "$AGENT_SH" | grep -v "^$" > /tmp/unguarded.txt || true
UNGUARDED=$(grep -c . /tmp/unguarded.txt 2>/dev/null || true)
# Example output blocks near the end still include bare `gh pr create` in
# illustrative sample console output. Allow a small quota for those.
if [ "$UNGUARDED" -le 4 ]; then
  pass "no unguarded gh pr create in operational code blocks (allowing $UNGUARDED in illustrative examples)"
else
  fail "found $UNGUARDED unguarded gh pr create calls in code blocks" "$(cat /tmp/unguarded.txt)"
fi

# ─────────────────────────────────────────────────────────
# /wrap — session_duration_ms derivation present
# ─────────────────────────────────────────────────────────

echo
echo "── /wrap duration computation ──"

# Session duration is derived from transcript timestamps at archive time
# (bin/transcript-archive.sh), defaulting to 0 when either end is unknown.
ARCHIVE_SH="$SCRIPT_DIR/bin/transcript-archive.sh"
if grep -qE 'DURATION_MS=\$\(\(END_EPOCH - START_EPOCH\)\)' "$ARCHIVE_SH"; then
  pass "session_duration_ms is computed from transcript start and end"
else
  fail "session_duration_ms is no longer computed at archive time"
fi
if grep -qE '^\s*DURATION_MS=0$' "$ARCHIVE_SH" \
   && grep -qE '"\$START_EPOCH" -gt 0.*"\$END_EPOCH" -gt 0' "$ARCHIVE_SH"; then
  pass "duration defaults to 0 and arithmetic is gated on both epochs"
else
  fail "duration arithmetic is not guarded" "a missing timestamp could break the archive step"
fi

# ─────────────────────────────────────────────────────────
# CLAUDE.md — branch-guard protocol section added
# ─────────────────────────────────────────────────────────

echo
echo "── CLAUDE.md protocol ──"

if grep -q "Branch-guard protocol" "$CLAUDE_MD"; then
  pass "CLAUDE.md has 'Branch-guard protocol' section"
else
  fail "CLAUDE.md missing 'Branch-guard protocol' section"
fi

if grep -q "Plan mode is \*\*not\*\* blocked" "$CLAUDE_MD"; then
  pass "CLAUDE.md documents plan-mode soften"
else
  fail "CLAUDE.md does not document plan-mode soften"
fi

# ─────────────────────────────────────────────────────────
# Summary
# ─────────────────────────────────────────────────────────

echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
